CREATE TABLE [dbo].[ccGenAgent](	  [timegroup] SMALLDATETIME NOT NULL	, [user_id] SMALLINT NOT NULL	, [tlog] SMALLINT NOT NULL DEFAULT(0)	, [treq] SMALLINT NOT NULL DEFAULT(0)	, [tnot_av] SMALLINT NOT NULL DEFAULT(0)	, [tav] SMALLINT NOT NULL DEFAULT(0)	, [tprob] SMALLINT NOT NULL DEFAULT(0)	, [tunknown] SMALLINT NOT NULL DEFAULT(0)	, [tother] SMALLINT NOT NULL DEFAULT(0)	, [nother] SMALLINT NOT NULL DEFAULT(0)	, [nMoh] SMALLINT NOT NULL DEFAULT((0))	, [nWHag] SMALLINT NOT NULL DEFAULT((0))	, [nWHcl] SMALLINT NOT NULL DEFAULT((0))	, CONSTRAINT [PK_ccGenAgent] PRIMARY KEY ([timegroup] ASC, [user_id] ASC))